grammar:
grammar Spaced {
  @whitespace: javaStyle
  @root
  Root ::= { S } ;
  @autoCommit
  S ::= 'k' B ;
  B ::= 'b' ;
}

grammar Roots {
  @root @autoCommit
  A ::= 'a' N ;
  @root
  @autoCommit
  B ::= 'b' N ;
  N ::= 'n' ;
}

grammar Recover {
  @root
  Root ::= { S } ;
  @autoCommit @recovery(sync=';')
  S ::= 'k' N ';' ;
  N ::= 'n' ;
}

grammar Unused {
  @root
  Root ::= 'r' N ;
  @autoCommit
  Lost ::= 'l' N ;
  N ::= 'n' ;
}

grammar Kept {
  @root
  Root ::= Item 'x' | 'a' 'y' ;
  @autoCommit
  Item ::= 'a' B ;
  B ::= 'b' ;
}
